package com.local.botarena;
import android.app.NativeActivity;
import android.os.Bundle;
import android.os.Handler;
import android.os.SystemClock;
import android.view.View;
import android.view.WindowManager;
import android.media.AudioManager;
import android.media.MediaPlayer;
import android.media.SoundPool;
import java.util.Arrays;
import java.util.Random;
public class MainActivity extends NativeActivity implements AudioManager.OnAudioFocusChangeListener{
 static{System.loadLibrary("botarena");}private native int getHumanAudioState();
 private SoundPool pool;private MediaPlayer music;private AudioManager manager;
 private final int[] ids=new int[10],voices=new int[9],steps=new int[2],lastStep=new int[64],voiceStreams=new int[9];
 private final boolean[] loaded=new boolean[10],voiceLoaded=new boolean[9],stepLoaded=new boolean[2];
 private final Handler handler=new Handler();private final Random random=new Random();
 private boolean resumed=false,focused=false,hasFocus=false,dead=false,terror=false,ducked=false;private long nextVoiceAt=0,voiceDuckUntil=0;
 private final Runnable audioTick=new Runnable(){@Override public void run(){pollHumanAudio();synchronized(MainActivity.this){if(!dead&&resumed&&focused&&hasFocus)handler.postDelayed(this,140);}}};
 @Override public void onCreate(Bundle state){super.onCreate(state);getWindow().addFlags(WindowManager.LayoutParams.FLAG_FULLSCREEN|WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);setVolumeControlStream(AudioManager.STREAM_MUSIC);manager=(AudioManager)getSystemService(AUDIO_SERVICE);terror=getArenaSettings()>=100;Arrays.fill(lastStep,-1);createAudio();hideBars();}
 @SuppressWarnings("deprecation") private synchronized void createAudio(){pool=new SoundPool(14,AudioManager.STREAM_MUSIC,0);pool.setOnLoadCompleteListener(new SoundPool.OnLoadCompleteListener(){@Override public void onLoadComplete(SoundPool p,int id,int status){synchronized(MainActivity.this){for(int i=0;i<10;i++)if(ids[i]==id)loaded[i]=status==0;for(int i=0;i<9;i++)if(voices[i]==id)voiceLoaded[i]=status==0;for(int i=0;i<2;i++)if(steps[i]==id)stepLoaded[i]=status==0;}}});int[] r={R.raw.arma_pistola,R.raw.arma_revolver,R.raw.arma_smg,R.raw.arma_fuzil,R.raw.arma_ak,R.raw.arma_escopeta,R.raw.arma_sniper,R.raw.arma_metralha,R.raw.arma_carabina,R.raw.arma_dupla};for(int i=0;i<10;i++)ids[i]=pool.load(this,r[i],1);int[] v={R.raw.humano_0_a,R.raw.humano_0_b,R.raw.humano_0_c,R.raw.humano_1_a,R.raw.humano_1_b,R.raw.humano_1_c,R.raw.humano_2_a,R.raw.humano_2_b,R.raw.humano_2_c};for(int i=0;i<9;i++)voices[i]=pool.load(this,v[i],1);steps[0]=pool.load(this,R.raw.passo_0,1);steps[1]=pool.load(this,R.raw.passo_1,1);nextVoiceAt=SystemClock.uptimeMillis()+1800;createMusic();}
 private synchronized void createMusic(){if(music!=null)music.release();music=MediaPlayer.create(this,terror?R.raw.arena_terror:R.raw.arena_fundo);if(music!=null){music.setLooping(true);music.setVolume(.16f,.16f);}}
 public int getArenaSettings(){return getSharedPreferences("arena_settings",MODE_PRIVATE).getInt("loadout",103);}public void saveArenaSettings(int p){getSharedPreferences("arena_settings",MODE_PRIVATE).edit().putInt("loadout",p).apply();}
 public void setTerrorMode(final boolean value){runOnUiThread(new Runnable(){@Override public void run(){synchronized(MainActivity.this){if(dead||terror==value)return;terror=value;if(pool!=null)for(int i=0;i<9;i++){if(voiceStreams[i]!=0)pool.stop(voiceStreams[i]);voiceStreams[i]=0;}voiceDuckUntil=0;nextVoiceAt=SystemClock.uptimeMillis()+1800;createMusic();updateAudio();}}});}
 public synchronized void playWeaponSound(int w){if(!dead&&resumed&&focused&&hasFocus&&pool!=null&&w>=0&&w<10&&loaded[w])pool.play(ids[w],.85f,.85f,1,0,1f);}
 private synchronized void scheduleAudio(){handler.removeCallbacks(audioTick);if(!dead&&resumed&&focused&&hasFocus)handler.postDelayed(audioTick,140);}
 private synchronized void pollHumanAudio(){if(dead||!resumed||!focused||!hasFocus||pool==null)return;long now=SystemClock.uptimeMillis();int state=getHumanAudioState();if(state>=0){float distance=(state>>>16)/12f;int kind=(state>>>14)&3,step=(state>>>13)&1,id=state&63;float pan=((state>>>6)&127)/63.5f-1,left=(float)Math.sqrt((1-pan)*.5f),right=(float)Math.sqrt((1+pan)*.5f),gain=.64f/(1+.065f*distance*distance);if(ducked)gain*=.35f;if(terror&&kind<3&&now>=nextVoiceAt){int clip=kind*3+random.nextInt(3);if(voiceLoaded[clip]){voiceStreams[clip]=pool.play(voices[clip],gain*left,gain*right,2,0,.96f+random.nextFloat()*.08f);voiceDuckUntil=now+2900;nextVoiceAt=now+3200+random.nextInt(4000);}else nextVoiceAt=now+600;}if(lastStep[id]!=-1&&lastStep[id]!=step&&distance<9&&stepLoaded[step])pool.play(steps[step],gain*.47f*left,gain*.47f*right,1,0,.94f+random.nextFloat()*.1f);lastStep[id]=step;}else if(nextVoiceAt<now)nextVoiceAt=now+800;if(music!=null){float vol=ducked?.035f:(terror&&now<voiceDuckUntil?.065f:.16f);music.setVolume(vol,vol);}}
 @SuppressWarnings("deprecation") private synchronized void updateAudio(){if(dead)return;boolean active=resumed&&focused;if(active&&!hasFocus&&manager!=null)hasFocus=manager.requestAudioFocus(this,AudioManager.STREAM_MUSIC,AudioManager.AUDIOFOCUS_GAIN)==AudioManager.AUDIOFOCUS_REQUEST_GRANTED;if(music!=null){if(active&&hasFocus){music.setVolume(ducked?.035f:.16f,ducked?.035f:.16f);if(!music.isPlaying())music.start();}else if(music.isPlaying())music.pause();}if(!active){if(pool!=null)pool.autoPause();if(hasFocus&&manager!=null)manager.abandonAudioFocus(this);hasFocus=false;}else if(hasFocus&&pool!=null)pool.autoResume();scheduleAudio();}
 @Override public void onResume(){super.onResume();synchronized(this){resumed=true;}hideBars();updateAudio();}@Override public void onPause(){synchronized(this){resumed=false;}updateAudio();super.onPause();}@Override public void onWindowFocusChanged(boolean value){super.onWindowFocusChanged(value);synchronized(this){focused=value;}if(value)hideBars();updateAudio();}
 @Override public synchronized void onAudioFocusChange(int change){if(dead)return;if(change==AudioManager.AUDIOFOCUS_GAIN){hasFocus=true;ducked=false;if(resumed&&focused){if(music!=null){music.setVolume(.16f,.16f);if(!music.isPlaying())music.start();}if(pool!=null)pool.autoResume();}}else if(change==AudioManager.AUDIOFOCUS_LOSS_TRANSIENT_CAN_DUCK){ducked=true;if(music!=null)music.setVolume(.035f,.035f);}else{hasFocus=false;if(music!=null&&music.isPlaying())music.pause();if(pool!=null)pool.autoPause();}scheduleAudio();}
 @SuppressWarnings("deprecation") @Override public void onDestroy(){synchronized(this){dead=true;resumed=focused=false;handler.removeCallbacks(audioTick);if(music!=null){music.release();music=null;}if(pool!=null){pool.release();pool=null;}if(manager!=null)manager.abandonAudioFocus(this);}super.onDestroy();}
 private void hideBars(){getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LAYOUT_STABLE|View.SYSTEM_UI_FLAG_LAYOUT_HIDE_NAVIGATION|View.SYSTEM_UI_FLAG_HIDE_NAVIGATION|View.SYSTEM_UI_FLAG_FULLSCREEN|View.SYSTEM_UI_FLAG_LAYOUT_FULLSCREEN|View.SYSTEM_UI_FLAG_IMMERSIVE_STICKY);}
}
